using Licitaciones.Application.Aprobaciones;
using Licitaciones.Domain.Aprobaciones;
namespace Licitaciones.UnitTests.Application.Aprobaciones;
public sealed class NivelAprobacionServiceTests
{ [Fact] public async Task Determinar_ConsultaRangosConfigurados() { var r = new Repo(); await r.AgregarAsync(new NivelAprobacion("Área", .01m, 999999.99m)); await r.AgregarAsync(new NivelAprobacion("Gerencia", 1000000m, 9999999.99m)); var s = new NivelAprobacionService(r); Assert.Equal("Gerencia", (await s.DeterminarAsync(2500000m)).Responsable); } [Fact] public async Task Crear_Traslapado_Rechaza() { var r = new Repo(); var s = new NivelAprobacionService(r); await s.CrearAsync("A", 1m, 100m); await Assert.ThrowsAsync<RangoAprobacionTraslapadoException>(() => s.CrearAsync("B", 100m, 200m)); } private sealed class Repo : INivelAprobacionRepository { readonly List<NivelAprobacion> x = []; public Task AgregarAsync(NivelAprobacion n, CancellationToken c = default) { x.Add(n); return Task.CompletedTask; } public Task<NivelAprobacion?> ObtenerAsync(Guid i, CancellationToken c = default) => Task.FromResult(x.SingleOrDefault(n => n.Id == i)); public Task<IReadOnlyList<NivelAprobacion>> ListarAsync(CancellationToken c = default) => Task.FromResult<IReadOnlyList<NivelAprobacion>>(x); public Task GuardarAsync(CancellationToken c = default) => Task.CompletedTask; public Task EliminarAsync(NivelAprobacion n, CancellationToken c = default) { x.Remove(n); return Task.CompletedTask; } } }
